import { db } from './firebase';
import { FieldValue, Timestamp } from 'firebase-admin/firestore';

type MessageRole = 'user' | 'assistant';

export async function ensureSession(
  sessionId: string,
  userId: string,
  title: string
): Promise<void> {
  const ref = db.collection('sessions').doc(sessionId);
  const existing = await ref.get();

  const payload: Record<string, unknown> = {
    userId,
    status: 'active',
    createdAt: FieldValue.serverTimestamp(),
  };

  if (!existing.exists || !existing.data()?.title) {
    payload.title = title;
  }

  await ref.set(payload, { merge: true });
}

export async function writeMessage(
  sessionId: string,
  role: MessageRole,
  content: string,
  attachment?: { videoUrl?: string; videoName?: string }
): Promise<void> {
  await db.collection('sessions').doc(sessionId).collection('messages').add({
    role,
    content,
    ...(attachment?.videoUrl ? { videoUrl: attachment.videoUrl } : {}),
    ...(attachment?.videoName ? { videoName: attachment.videoName } : {}),
    createdAt: FieldValue.serverTimestamp(),
  });

  await db.collection('sessions').doc(sessionId).set(
    {
      lastMessageAt: FieldValue.serverTimestamp(),
      messageCount: FieldValue.increment(1),
    },
    { merge: true }
  );
}

export async function getRecentMessages(
  sessionId: string,
  limitCount: number = 50
): Promise<{ role: string; content: string }[]> {
  const snapshot = await db
    .collection('sessions')
    .doc(sessionId)
    .collection('messages')
    .orderBy('createdAt', 'asc')
    .limit(limitCount)
    .get();

  if (snapshot.empty) {
    return [];
  }

  return snapshot.docs.map((doc) => {
    const data = doc.data();
    return {
      role: data.role as string,
      content: data.content as string,
    };
  });
}

export async function getUserSessions(
  userId: string,
  limitCount: number = 20
): Promise<
  { sessionId: string; title: string; lastMessageAt: Date; messageCount: number }[]
> {
  const snapshot = await db
    .collection('sessions')
    .where('userId', '==', userId)
    .get();

  const sessions: {
    sessionId: string;
    title: string;
    lastMessageAt: Date;
    messageCount: number;
  }[] = [];

  for (const doc of snapshot.docs) {
    const data = doc.data();
    const lastMessageAtRaw = data.lastMessageAt ?? data.createdAt;
    if (!lastMessageAtRaw) {
      continue;
    }

    const lastMessageAt =
      lastMessageAtRaw instanceof Timestamp
        ? lastMessageAtRaw.toDate()
        : new Date(lastMessageAtRaw);

    sessions.push({
      sessionId: doc.id,
      title: (data.title as string) || 'Untitled Chat',
      lastMessageAt,
      messageCount: (data.messageCount as number) ?? 0,
    });
  }

  return sessions
    .sort((a, b) => b.lastMessageAt.getTime() - a.lastMessageAt.getTime())
    .slice(0, limitCount);
}
